/**
 * Google Pack (Apache-2.0) browser resource linker for its SUPPORTED subset.
 * This does not run or impersonate Google's full native AAPT2.
 *
 * The actual resource table is generated by Pack WASM and returns its own R IDs.
 * Kotlin must be rebuilt with these authoritative IDs before DEX is packaged.
 */
import {developmentPem,to64,from64} from './crypto.mjs';
import {isGeneratedPath} from './analyzer.mjs';
let session=null,wasm=null;
const $=id=>document.getElementById(id);
const info=s=>{const box=$('realResourcesLog');if(box){box.textContent+='\n['+new Date().toLocaleTimeString('fr-FR')+'] '+s;box.scrollTop=box.scrollHeight;}};
const uiStatus=(s,good=false)=>{const x=$('realResourcesStatus');if(x){x.className='alert'+(good?' good':'');x.textContent=s;}};
const allowedBin=/\.(?:png|webp|jpg|jpeg)$/i;
const symbolsFromSources=code=>[...code.matchAll(/\bR\.([A-Za-z_]\w*)\.([A-Za-z_]\w*)/g)].map(x=>x[1]+'/'+x[2]);
export function resourceBlockers({resourcePaths,manifest,sourceTexts}){
 const reasons=[];
 for(const path of resourcePaths){
  if(isGeneratedPath(path)){reasons.push('Fichier généré refusé : '+path);continue;}
  const match=path.match(/(?:^|\/)res\/([^/]+)\/([^/]+)$/);
  if(!match){reasons.push('Chemin res/ non supporté : '+path);continue;}
  const kind=match[1],name=match[2];
  if(kind.includes('-'))reasons.push('Qualificateur de ressources non pris en charge : '+path);
  else if(kind==='values'&&name!=='strings.xml')reasons.push('Valeurs Android hors strings.xml (style/couleur/thème) : '+path);
  else if(kind==='values'){}
  else if(kind==='xml' && name.endsWith('.xml')){}
  else if(kind==='raw'){}
  else if((kind==='drawable'||kind==='mipmap')&&allowedBin.test(name)){}
  else reasons.push('Ressource XML/layout/drawable non prise en charge par Google Pack : '+path);
 }
 if(!/<manifest\b/.test(manifest))reasons.push('Balise racine <manifest> absente.');
 if(/android:hasCode\s*=\s*["']false["']/.test(manifest))reasons.push('android:hasCode=false interdit pour les sources Kotlin.');
 if(/(?:@style\/|\?attr\/|@\+id\/|\$\{)/.test(manifest))reasons.push('Le manifeste utilise des thèmes, attributs ou placeholders que Pack ne sait pas lier.');
 for(const source of sourceTexts){
  if(/R\.(?:id|style|color|dimen|attr|integer|bool|plurals|array)\./.test(source)){
   reasons.push('Les sources utilisent des IDs/styles/valeurs qui exigent le vrai AAPT2 (non encore porté).');
   break;
  }
 }
 return [...new Set(reasons)];
}
export function linkedRCode(namespace,ids,sourceTexts=[]){
 if(typeof namespace!=='string'||!/^[A-Za-z_]\w*(?:\.[A-Za-z_]\w*)+$/.test(namespace))
  throw Error('Namespace Android invalide pour R.kt.');
 if(!ids||typeof ids!=='object')throw Error('Table de ressources WASM absente.');
 const refs=new Set(sourceTexts.flatMap(symbolsFromSources));
 const missing=[...refs].filter(x=>!Object.hasOwn(ids,x));
 if(missing.length)throw Error('IDs R absents du resources.arsc réel : '+missing.join(', '));
 let result='package '+namespace+'\n\n/** IDs extraits du resources.arsc réel construit par Pack. */\nobject R {\n';
 const kinds=new Map();
 for(const [key,id] of Object.entries(ids)){
  const parts=key.split('/');
  if(parts.length!==2||!parts.every(s=>/^[A-Za-z_]\w*$/.test(s))||!Number.isInteger(id)||id<0x7f010000)
   throw Error('Ressource réelle invalide : '+key);
  if(!kinds.has(parts[0]))kinds.set(parts[0],[]);
  kinds.get(parts[0]).push({name:parts[1],id});
 }
 for(const [kind,values] of [...kinds].sort(([a],[b])=>a.localeCompare(b))){
  result+='  object '+kind+' {\n';
  for(const v of values.sort((a,b)=>a.name.localeCompare(b.name))){
   result+='    const val '+v.name+': Int = 0x'+v.id.toString(16)+'\n';
  }
  result+='  }\n';
 }
 return result+'}\n';
}
export function normalizedManifest(xml,analysis){
 const name=analysis.packageName;
 if(!/^[A-Za-z_]\w*(?:\.[A-Za-z_]\w*)+$/.test(name))throw Error('applicationId invalide.');
 if(!/<manifest\b[^>]*>/.test(xml))throw Error('AndroidManifest.xml source invalide.');
 if(!/xmlns:android\s*=/.test(xml))throw Error('Espace de noms Android manquant.');
 const min=Number(analysis.minSdk),target=Number(analysis.targetSdk),versionCode=Number(analysis.versionCode);
 if(!Number.isInteger(min)||min<21||min>36||!Number.isInteger(target)||target<min||target>36)
  throw Error('Valeurs SDK incompatibles avec la chaîne actuelle.');
 if(!Number.isInteger(versionCode)||versionCode<1)throw Error('versionCode Gradle absent ou invalide.');
 if(typeof analysis.version!=='string'||!/^[A-Za-z0-9._-]+$/.test(analysis.version))throw Error('versionName Gradle invalide.');
 let result=xml.replace(/<manifest\b[^>]*>/,tag=>{
  const attr=(key,val)=>{const exp=new RegExp('\\b'+key+'\\s*=\\s*["\\x27][^"\\x27]*["\\x27]');
   return exp.test(tag)?tag.replace(exp,key+'="'+val+'"'):tag.slice(0,-1)+' '+key+'="'+val+'">';
  };
  tag=attr('package',name);
  tag=attr('android:versionCode',String(versionCode));
  return attr('android:versionName',analysis.version);
 });
 if(!/<uses-sdk\b/.test(result)){
  result=result.replace(/<manifest\b[^>]*>/,m=>m+'\n<uses-sdk android:minSdkVersion="'+min+'" android:targetSdkVersion="'+target+'"/>');
 }
 return result;
}
async function engine(){
 if(wasm)return wasm;
 const m=await import('../wasm/pack/pack_wasm.js');
 await m.default();
 if(typeof m.apkforge_resource_ids!=='function'||typeof m.apkforge_sign_with_dex!=='function')
  throw Error('Google Pack WASM doit être reconstruit avec les extensions APK Forge.');
 wasm=m;return m;
}
export function refreshApkButton(sourceZip,artifact){
 const button=$('realApkAssemble');
 if(button)button.disabled=!(sourceZip&&session?.zip===sourceZip&&artifact?.linkedResourceSession===session&&artifact.runtimeZip);
}
export function getResourceSession(project){
 return project?.zip&&session?.zip===project.zip?session:null;
}
export async function prepareRealResources(project){
 const data=project?.analysis;if(!project?.zip||!data)throw Error('Importe d’abord un ZIP Android.');
 const resourcePaths=data.resourcePaths??[];
 const path=data.manifestPath;
 if(!path||!project.files[path])throw Error('AndroidManifest.xml source absent.');
 const xml=await project.files[path].async('string');
 const sourceFiles=(data.sourceSamples??[]).filter(x=>x.endsWith('.kt'));
 const sourceTexts=await Promise.all(sourceFiles.map(x=>project.files[x].async('string')));
 const reasons=resourceBlockers({resourcePaths,manifest:xml,sourceTexts});
 const textResources=[];
 for(const p of resourcePaths){
  if(p.endsWith('.xml')){
   const text=await project.files[p].async('string');
   if(/\/res\/values\/strings\.xml$/.test(p)&&/<\s*(?:style|color|dimen|bool|integer|plurals|array|string-array|item)\b/.test(text))
    reasons.push('Valeurs complexes non prises en charge dans strings.xml : '+p);
   if(/\/res\/values\/strings\.xml$/.test(p)&&/<string\b[^>]*\bformatted\s*=/.test(text))
    reasons.push('Formatage de strings.xml non validé : '+p);
   if(/[?]attr\/|@style\/|@\+id\//.test(text))
    reasons.push('Références complexes dans '+p);
   textResources.push({path:p,text});
  }
 }
 if(reasons.length)throw Error('Google Pack ne peut pas compiler ce projet comme AAPT2 :\n• '+[...new Set(reasons)].join('\n• '));
 const manifest=normalizedManifest(xml,data);
 const resources=await Promise.all(resourcePaths.map(async p=>{
  const match=p.match(/(?:^|\/)res\/([^/]+)\/([^/]+)$/);
  if(!match)throw Error('Chemin res/ mal formé : '+p);
  const file=project.files[p];
  if((file._data?.uncompressedSize??0)>8*1024*1024)throw Error('Ressource >8 Mio : '+p);
  return {subdirectory:match[1],name:match[2],contents_b64:to64(new Uint8Array(await file.async('uint8array')))};
 }));
 const combined_pem_string=await developmentPem();
 const input={manifest_b64:to64(new TextEncoder().encode(manifest)),resources,combined_pem_string,generate_aab:false};
 info('Compilation du manifeste et des ressources avec Google Pack WebAssembly...');
 const wasm=await engine();
 const ids=wasm.apkforge_resource_ids(input);
 linkedRCode(data.namespace!=='Non précisé'?data.namespace:data.packageName,ids,sourceTexts);
 const signedResources=wasm.build(input);
 const b=new Blob([from64(signedResources)],{type:'application/vnd.android.package-archive'});
 const zip=await JSZip.loadAsync(b);
 for(const [name,magic] of [['AndroidManifest.xml',3],['resources.arsc',2]]){
  const file=zip.file(name);if(!file)throw Error('Ressource binaire manquante : '+name);
  const bytes=await file.async('uint8array');
  if(bytes[0]!==magic||bytes[1]!==0)throw Error('En-tête binaire invalide pour '+name);
 }
 session={zip:project.zip,project,ids,input,sourceTexts,namespace:data.namespace!=='Non précisé'?data.namespace:data.packageName};
 refreshApkButton(project.zip,null);
 info('Ressources compilées : manifeste binaire, resources.arsc, '+Object.keys(ids).length+' identifiants Android réels.');
 info('Il faut maintenant RECOMPILER Kotlin avec ces identifiants avant la fusion D8.');
 return session;
}
export async function assembleRealApk(project,artifact){
 const prepared=getResourceSession(project);
 if(!prepared)throw Error('Compile les ressources avec Google Pack avant de construire un APK.');
 if(artifact?.linkedResourceSession!==prepared||!artifact.runtimeZip)
  throw Error('Recompile Kotlin avec les IDs R réels, puis exécute la fusion D8. Les anciens DEX de diagnostic ne sont pas acceptés.');
 const zip=await JSZip.loadAsync(artifact.runtimeZip);
 const names=Object.keys(zip.files).filter(x=>/^classes(?:[2-9]|\d{2})?\.dex$/.test(x)).sort((a,b)=>{
  const n=x=>x==='classes.dex'?1:Number(x.replace(/\D/g,''));return n(a)-n(b);
 });
 if(names.length===0)throw Error('Aucun DEX runtime valide.');
 const payload=[];
 for(let i=0;i<names.length;i++){
  const expected=i===0?'classes.dex':'classes'+(i+1)+'.dex';
  if(names[i]!==expected)throw Error('Nommage DEX non contigu : '+names[i]);
  const bytes=await zip.file(names[i]).async('uint8array');
  if(bytes.length<8||bytes[0]!==100||bytes[1]!==101||bytes[2]!==120||bytes[3]!==10)
   throw Error('DEX invalide : '+names[i]);
  payload.push(to64(bytes));
 }
 info('Assemblage ZIP, alignement et signature v2/v3 APRÈS insertion de '+payload.length+' DEX...');
 const wasm=await engine();
 const out=new Blob([from64(wasm.apkforge_sign_with_dex(prepared.input,payload))],{type:'application/vnd.android.package-archive'});
 const finalZip=await JSZip.loadAsync(out);
 for(const name of ['AndroidManifest.xml','resources.arsc',...names]){
  if(!finalZip.file(name))throw Error('APK incomplet : '+name);
 }
 info('APK signé construit dans Chrome ('+(out.size/1024).toFixed(1)+' Kio). Signature à vérifier avant installation.');
 return out;
}
function save(blob,name){
 const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;
 document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),30000);
}
export function attachRealResourceCompiler(getProject,getArtifacts){
 $('realResourcesPrepare')?.addEventListener('click',async()=>{
  const button=$('realResourcesPrepare');button.disabled=true;
  uiStatus('Compilation et validation des ressources en cours...');
  try{
   const prepared=await prepareRealResources(getProject());
   uiStatus('Ressources compilées. '+Object.keys(prepared.ids).length+' IDs R réels prêts. Recompile maintenant Kotlin puis D8.',true);
  }catch(e){
   session=null;uiStatus('Ressources non compilées : '+e.message);info('BLOCAGE : '+e.message);console.error('APK Forge resources',e);
  }finally{button.disabled=false;}
 });
 $('realApkAssemble')?.addEventListener('click',async()=>{
  const btn=$('realApkAssemble');btn.disabled=true;
  try{
   const project=getProject(),out=await assembleRealApk(project,getArtifacts());
   const name=(project.analysis.name||'android-app').replace(/[^a-z0-9._-]+/gi,'-');
   const version=(project.analysis.version||'1').replace(/[^a-z0-9._-]+/gi,'-');
   save(out,name+'-'+version+'-browser-debug.apk');
   uiStatus('APK téléchargé. Tester la signature avec apksigner et l’installation sur appareil avant toute utilisation.',true);
  }catch(e){
   uiStatus('APK non généré : '+e.message);info('BLOCAGE : '+e.message);console.error('APK Forge packager',e);
  }finally{btn.disabled=false;}
 });
}
